// Embeds scripts/max/glass2mdl_apply.py into a TS module so the browser-side
// export can ship the apply script inside every volumetric ZIP.
//
//   pnpm embed:max
//
// The generated file is committed; a test fails when it drifts from the
// source, so editing the .py always ends with re-running this.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = readFileSync(join(root, "scripts/max/glass2mdl_apply.py"), "utf8");

const out = `// GENERATED by scripts/embed-apply-script.mjs — do not edit by hand.
// Source of truth: scripts/max/glass2mdl_apply.py. Regenerate: pnpm embed:max
// (tests fail when this file drifts from the source).

/** The 3ds Max apply script, shipped inside every volumetric export ZIP. */
export const APPLY_SCRIPT: string = ${JSON.stringify(source)};
`;

const target = join(root, "src/engine/package/applyScript.generated.ts");
writeFileSync(target, out);
console.log(
  "embedded scripts/max/glass2mdl_apply.py -> src/engine/package/applyScript.generated.ts (%d chars)",
  source.length,
);
